object Solution {
  def minDays(grid: Array[Array[Int]]): Int = {
    val m = grid.length
    val n = grid(0).length

    // Directions for 4-neighbor traversal
    val directions = Array((1,0), (-1,0), (0,1), (0,-1))

    // Count islands in the grid
    def countIslands(): Int = {
      val visited = Array.fill(m, n)(false)
      def dfs(r: Int, c: Int): Unit = {
        visited(r)(c) = true
        for ((dr, dc) <- directions) {
          val nr = r + dr
          val nc = c + dc
          if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited(nr)(nc) && grid(nr)(nc) == 1) {
            dfs(nr, nc)
          }
        }
      }

      var islands = 0
      for (i <- 0 until m; j <- 0 until n) {
        if (grid(i)(j) == 1 && !visited(i)(j)) {
          islands += 1
          if (islands > 1) return islands // early stop if more than 1 island
          dfs(i, j)
        }
      }
      islands
    }

    // Check if grid is connected (exactly one island)
    def isConnected(): Boolean = countIslands() == 1

    // If already disconnected (0 or >1 islands), return 0
    if (!isConnected()) return 0

    // Try removing one land cell and check if disconnected
    for (i <- 0 until m; j <- 0 until n if grid(i)(j) == 1) {
      grid(i)(j) = 0
      if (!isConnected()) {
        grid(i)(j) = 1
        return 1
      }
      grid(i)(j) = 1
    }

    // Otherwise, answer is 2 (problem constraints guarantee max 2)
    2
  }
}

